/** A factorized distinct-key prefix must preserve the range that replaced its FILTER. */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class LmdbNativeFactorizedRangeParityTest {

	private static final String NATIVE = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final String NS = "urn:factorized-range:";
	private static final int ROWS = 64;
	private static final int FIRST = ROWS / 2;
	private static final String ROUTE = LmdbNativeAttemptMetrics.PATH_FACTORIZED_ROWS;
	private static final String BODY = "SELECT DISTINCT ?s WHERE { ?s <" + NS + "score> ?n . ?s <" + NS
			+ "tag> ?unused";
	@TempDir
	File directory;
	private final Map<String, String> previous = new LinkedHashMap<>();
	private LmdbStore store;
	private SailRepository repository;
	private SailRepository memoryRepository;

	@BeforeEach
	void configure() throws Exception {
		set(NATIVE, "true");
		set(LmdbNativeJaninoCodegen.ENABLED_PROPERTY, "false");
		set(LmdbNativeJaninoCodegen.SYNCHRONOUS_PROPERTY, "true");
		set(LmdbNativeJaninoCodegen.THRESHOLD_ROWS_PROPERTY, "0");
		set(LmdbNativeKernelInterpreter.ENABLED_PROPERTY, "false");
		set(LmdbNativeKernelLowering.HASH_JOIN_PROPERTY, "false");
		set(LmdbNativeKernelLowering.WCOJ_KERNEL_PROPERTY, "true");
		set("rdf4j.lmdb.wcoj.enabled", "false");
		set(LmdbNativeKernelLowering.SCAN_SOURCES_PROPERTY, "true");
		set("rdf4j.lmdb.native.rangePushdown", "true");
		set(LmdbNativeHashJoin.ENABLED_PROPERTY, "true");
		set(LmdbNativeHashJoin.MIN_ROWS_PROPERTY, "0");
		set("rdf4j.lmdb.parallel.enabled", "false");
		set("rdf4j.lmdb.packedFtree.enabled", "false");
		set("rdf4j.lmdb.factorizedRows.enabled", "true");
		set("rdf4j.lmdb.factorizedRows.keysOnlyRoot.enabled", "true");
		set(NativeBatch.ENABLED_PROPERTY, "false");
		store = new LmdbStore(directory, new LmdbStoreConfig("spoc,posc").setForceSync(false)
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(true)
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyBuildOnStart(false));
		repository = new SailRepository(store);
		memoryRepository = new SailRepository(new MemoryStore());
		var vf = SimpleValueFactory.getInstance();
		IRI score = vf.createIRI(NS + "score"), tag = vf.createIRI(NS + "tag");
		for (SailRepository target : List.of(repository, memoryRepository)) {
			target.init();
			try (SailRepositoryConnection connection = target.getConnection()) {
				connection.begin();
				for (int i = 0; i < ROWS; i++) {
					IRI subject = vf.createIRI(NS + "s" + i);
					connection.add(subject, score, vf.createLiteral(i));
					connection.add(subject, tag, vf.createIRI(NS + "tagValue"));
				}
				connection.commit();
			}
		}
		assertThat(AdjacencyEngagementTestAccess.buildNow(store)).isTrue();
	}

	@AfterEach
	void restore() {
		LmdbNativeDispatchLoop.observeSelections(null);
		try {
			if (repository != null) {
				repository.shutDown();
			}
		} finally {
			try {
				if (memoryRepository != null) {
					memoryRepository.shutDown();
				}
			} finally {
				previous.forEach((key, value) -> {
					if (value == null) {
						System.clearProperty(key);
					} else {
						System.setProperty(key, value);
					}
				});
			}
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { true, false })
	void aFactorizedRootRetainsItsRangeWithoutDisablingPlainKeys(boolean ranged) throws Exception {
		String query = BODY + (ranged ? " . FILTER(?n >= " + FIRST + ")" : "") + " }";
		Map<Value, Integer> expected = new LinkedHashMap<>();
		for (int i = ranged ? FIRST : 0; i < ROWS; i++) {
			expected.put(SimpleValueFactory.getInstance().createIRI(NS + "s" + i), 1);
		}
		assertThat(bag(memoryRepository, query)).as("explicit unique-subject MemoryStore bag").isEqualTo(expected);
		set(NATIVE, "false");
		assertThat(bag(repository, query)).as("generic LMDB preserves the exact range").isEqualTo(expected);
		set(NATIVE, "true");
		Optimized optimized = optimizeAndRun(query);
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			var triples = new SailDatasetTripleTermSource(repository.getValueFactory(), dataset);
			LmdbNativeEvaluationStrategy strategy = spy(new LmdbNativeEvaluationStrategy(triples, null, null, 0L,
					new EvaluationStatistics(), false));
			doReturn(ROUTE).when(strategy).forcedExecutionStrategyName();
			QueryEvaluationStep compiled = LmdbNativeAggregateCompiler.tryCompile(optimized.expression(),
					new QueryEvaluationContext.Minimal((Dataset) null), strategy, source);
			assertThat(compiled).isInstanceOf(NativeRowsStep.class);
			NativeRowsStep step = (NativeRowsStep) compiled;
			assertThat(step.distinct).isTrue();
			assertThat(step.targetNames).containsExactly("s");
			assertThat(step.arg).isInstanceOf(MultiJoinPlan.class);
			MultiJoinPlan join = (MultiJoinPlan) step.arg;
			assertThat(join.children).hasSize(2);
			assertThat(join.filters).as("the executable range replaces its explicit FILTER").isEmpty();
			List<PatternPlan> ranges = List.of(join.children)
					.stream()
					.filter(PatternPlan.class::isInstance)
					.map(PatternPlan.class::cast)
					.filter(pattern -> pattern.range != null)
					.toList();
			assertThat(ranges).hasSize(ranged ? 1 : 0);
			RowState row = new RowState(step.source, step.layout, EmptyBindingSet.getInstance());
			Map<Value, Integer> producerBag = new LinkedHashMap<>();
			List<String> selected = observe();
			boolean usedKeys;
			try {
				assertThat(LmdbNativeAggregateCompiler.initializeRow(row, row.base, row.source, row.layout)).isTrue();
				try (NativeUnorderedInput input = step.openUnorderedInput(row)) {
					LmdbNativeFactorizedRows factorized = input.factorizedAttempt;
					assertThat(factorized).as("the forced producer really opened factorized rows").isNotNull();
					assertThat(factorized.flatCount).isEqualTo(1);
					assertThat(factorized.derived.order[0]).isInstanceOf(PatternPlan.class);
					if (ranged) {
						assertThat(factorized.derived.order[0])
								.as("the range-bearing pattern is the actual prefix root")
								.isSameAs(ranges.getFirst());
					}
					usedKeys = "keysOnlyRoot".equals(factorized.prefixStrategy);
					if (!ranged) {
						assertThat(factorized.keysOnlyRoot).isNotNull();
						assertThat(usedKeys).as("the legal plain-key optimization remains active").isTrue();
						assertThat(factorized.keysOnlyRoot.pattern).isSameAs(factorized.derived.order[0]);
					} else {
						assertThat(usedKeys).as("range-bearing roots must not bypass their accepted-edge test")
								.isFalse();
						assertThat(factorized.keysOnlyRoot).as("a guarded range uses the ordinary exact prefix")
								.isNull();
					}
					while (input.advance()) {
						producerBag.merge(row.source.lazyValue(row.slots[step.sourceSlots[0]]), 1, Integer::sum);
					}
					input.markExhausted();
				}
			} finally {
				LmdbNativeDispatchLoop.observeSelections(null);
				row.memoryScope.close();
			}
			assertThat(selected).containsExactly(ROUTE);
			selected = observe();
			Map<Value, Integer> actual = new LinkedHashMap<>();
			try (var rows = compiled.evaluate(EmptyBindingSet.getInstance())) {
				while (rows.hasNext()) {
					actual.merge(rows.next().getValue("s"), 1, Integer::sum);
				}
			} finally {
				LmdbNativeDispatchLoop.observeSelections(null);
			}
			assertThat(selected).containsExactly(ROUTE);
			System.out.printf("factorized range=%s keysOnlyRoot=%s expected=%d producer=%d actual=%d%n", ranged,
					usedKeys, expected.size(), producerBag.size(), actual.size());
			assertThat(optimized.bag()).as("the normally optimized factorized route preserves its range")
					.isEqualTo(expected);
			assertThat(producerBag).as("the physically opened prefix does not widen the range").isEqualTo(expected);
			assertThat(actual).as("the complete factorized DISTINCT consumer returns the exact bag")
					.isEqualTo(expected);
		}
	}

	private static List<String> observe() {
		List<String> selected = new ArrayList<>();
		LmdbNativeDispatchLoop.observeSelections((target, label, id, record) -> {
			if (record.point() == LmdbNativeDecisionPoint.ROW) {
				selected.add(id);
			}
		});
		return selected;
	}

	private Optimized optimizeAndRun(String query) {
		List<TupleExpr> optimized = new ArrayList<>();
		Map<Value, Integer> bag = new LinkedHashMap<>();
		LmdbNativeDispatchLoop.observeSelections((target, label, id, record) -> {
			if (record.point() == LmdbNativeDecisionPoint.ROW) {
				assertThat(id).isEqualTo(ROUTE);
				assertThat(target).isNotNull();
				optimized.add(target.clone());
			}
		});
		try (var connection = repository.getConnection()) {
			SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(query);
			prepared.setForcedLmdbExecutionStrategy(ROUTE);
			prepared.setMaxExecutionTime(10);
			try (var rows = prepared.evaluate()) {
				while (rows.hasNext()) {
					bag.merge(rows.next().getValue("s"), 1, Integer::sum);
				}
			}
		} finally {
			LmdbNativeDispatchLoop.observeSelections(null);
		}
		assertThat(optimized).as("one actual optimized repository dispatch").hasSize(1);
		return new Optimized(optimized.getFirst(), bag);
	}

	private record Optimized(TupleExpr expression, Map<Value, Integer> bag) {
	}

	private Map<Value, Integer> bag(SailRepository target, String query) {
		Map<Value, Integer> bag = new LinkedHashMap<>();
		try (var connection = target.getConnection(); var rows = connection.prepareTupleQuery(query).evaluate()) {
			while (rows.hasNext()) {
				bag.merge(rows.next().getValue("s"), 1, Integer::sum);
			}
		}
		return bag;
	}

	private void set(String key, String value) {
		if (!previous.containsKey(key)) {
			previous.put(key, System.getProperty(key));
		}
		System.setProperty(key, value);
	}
}
